INSERT INTO public.breaking_news (text, sort_order, is_active) VALUES
('बिहार विधानसभा सत्र का आज दूसरा दिन, कई अहम मुद्दों पर होगी चर्चा', 1, true),
('पटना में मेट्रो का ट्रायल रन सफल, जल्द शुरू होगी यात्री सेवा', 2, true),
('मौसम विभाग का अलर्ट: अगले 48 घंटों में उत्तर बिहार में भारी बारिश की संभावना', 3, true),
