INSERT INTO public.news_articles
(slug, title, subtitle, summary, content, image_url, category_id, author_id, tags, status, is_featured, is_trending, featured_rank, published_at, view_count) VALUES
('patna-metro-trial-run-success','पटना मेट्रो का ट्रायल रन सफल, अगले महीने से शुरू होगी यात्री सेवा','राजधानी पटना के लोगों के लिए बड़ी खुशखबरी','पटना मेट्रो रेल कॉर्पोरेशन ने आज दानापुर से मीठापुर तक के पहले कॉरिडोर पर सफल ट्रायल रन पूरा कर लिया।',E'पटना मेट्रो रेल कॉर्पोरेशन ने आज दानापुर से मीठापुर तक के पहले कॉरिडोर पर सफल ट्रायल रन पूरा कर लिया। मुख्यमंत्री ने इसे राज्य के विकास का ऐतिहासिक दिन बताया।\n\nपहले चरण में कुल 12 स्टेशन होंगे और यात्रा का समय आधा हो जाएगा। किराया 10 से 50 रुपये के बीच रखा गया है।\n\nपरियोजना पर अब तक करीब 13,000 करोड़ रुपये खर्च हो चुके हैं।','https://images.unsplash.com/photo-1474487548417-781cb71495f3?w=1200&q=80',c_bihar,a,ARRAY['पटना','मेट्रो','बिहार'],'published',true,true,1,now()-interval '1 hour',1245),
('bihar-assembly-session-day2','बिहार विधानसभा: दूसरे दिन हंगामेदार रही कार्यवाही, विपक्ष का वॉकआउट','कानून व्यवस्था पर सरकार को घेरा','बिहार विधानसभा के मानसून सत्र के दूसरे दिन विपक्ष ने सरकार को घेरा और वॉकआउट किया।',E'बिहार विधानसभा के मानसून सत्र के दूसरे दिन विपक्ष ने कानून व्यवस्था के मुद्दे पर सरकार को जमकर घेरा। नेता प्रतिपक्ष ने कहा कि राज्य में अपराध बेकाबू हो चुका है।\n\nसरकार की ओर से गृह मंत्री ने जवाब देते हुए कहा कि पिछले एक साल में बड़ी संख्या में अपराधियों को गिरफ्तार किया गया है।','https://images.unsplash.com/photo-1555848962-6e79363ec58f?w=1200&q=80',c_politics,a,ARRAY['विधानसभा','राजनीति'],'published',true,true,2,now()-interval '3 hours',890),
('india-australia-t20-series','भारत ने ऑस्ट्रेलिया को टी-20 सीरीज़ में 3-1 से हराया','विराट कोहली का शानदार शतक','भारतीय क्रिकेट टीम ने ऑस्ट्रेलिया के खिलाफ टी-20 सीरीज़ 3-1 से जीती। कोहली ने नाबाद 102 रन बनाए।',E'भारतीय क्रिकेट टीम ने ऑस्ट्रेलिया के खिलाफ पांच मैचों की टी-20 सीरीज़ 3-1 से अपने नाम कर ली। आख़िरी मैच में विराट कोहली ने 58 गेंदों पर नाबाद 102 रन की पारी खेली।\n\nगेंदबाज़ी में जसप्रीत बुमराह ने 4 ओवर में सिर्फ़ 18 रन देकर 3 विकेट लिए।','https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?w=1200&q=80',c_sports,a,ARRAY['क्रिकेट','भारत'],'published',true,true,3,now()-interval '5 hours',2310),
('monsoon-alert-north-bihar','मौसम अलर्ट: उत्तर बिहार के 12 ज़िलों में भारी बारिश की चेतावनी','अगले 48 घंटे महत्वपूर्ण','IMD ने उत्तर बिहार के 12 ज़िलों में अगले 48 घंटों के दौरान भारी बारिश की चेतावनी जारी की है।',E'भारतीय मौसम विभाग (IMD) ने उत्तर बिहार के 12 ज़िलों में अगले 48 घंटों के दौरान भारी से बहुत भारी बारिश की चेतावनी जारी की है।\n\nइन ज़िलों में मुजफ़्फ़रपुर, दरभंगा, मधुबनी, सीतामढ़ी, शिवहर, चंपारण, सहरसा, सुपौल, अररिया, पूर्णिया और किशनगंज शामिल हैं।\n\nNDRF की कई टीमें तैनात कर दी गई हैं।','https://images.unsplash.com/photo-1519692933481-e162a57d6721?w=1200&q=80',c_bihar,a,ARRAY['मौसम','बिहार'],'published',true,false,4,now()-interval '7 hours',670),
('startup-india-funding','भारतीय स्टार्टअप्स को मिली रिकॉर्ड फंडिंग, बिहार के तीन स्टार्टअप भी शामिल','पिछले महीने 2.1 अरब डॉलर का निवेश','भारतीय स्टार्टअप्स को पिछले महीने रिकॉर्ड 2.1 अरब डॉलर की फंडिंग मिली।','भारतीय स्टार्टअप इकोसिस्टम के लिए अच्छी ख़बर है। पिछले महीने देश के स्टार्टअप्स को कुल 2.1 अरब डॉलर की फंडिंग प्राप्त हुई जो पिछले दो साल का सबसे बड़ा आंकड़ा है। बिहार के भी तीन स्टार्टअप्स इस सूची में शामिल हैं।','https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=1200&q=80',c_business,a,ARRAY['स्टार्टअप'],'published',true,true,5,now()-interval '9 hours',540),
('education-bihar-stet-result','बिहार STET 2026 का परिणाम घोषित, 68% अभ्यर्थी हुए सफल','बीएसईबी ने जारी किया रिज़ल्ट','बिहार विद्यालय परीक्षा समिति ने आज STET 2026 का परिणाम घोषित कर दिया।','बिहार विद्यालय परीक्षा समिति (BSEB) ने आज माध्यमिक शिक्षक पात्रता परीक्षा (STET) 2026 का परिणाम घोषित कर दिया। कुल 68% अभ्यर्थी सफल घोषित किए गए हैं।','https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1200&q=80',c_education,a,ARRAY['शिक्षा','STET'],'published',false,true,NULL,now()-interval '12 hours',1820),
('world-climate-summit-india','जलवायु सम्मेलन में भारत ने रखा बड़ा प्रस्ताव, दुनिया ने सराहा','पीएम मोदी का संबोधन','यूएन जलवायु सम्मेलन में भारत ने 2030 तक नवीकरणीय ऊर्जा क्षमता दोगुनी करने का प्रस्ताव रखा।','संयुक्त राष्ट्र जलवायु सम्मेलन में प्रधानमंत्री ने भारत की ओर से एक महत्वाकांक्षी प्रस्ताव पेश किया जिसमें 2030 तक देश की नवीकरणीय ऊर्जा क्षमता दोगुनी करने की प्रतिबद्धता शामिल है।','https://images.unsplash.com/photo-1466611653911-95081537e5b7?w=1200&q=80',c_world,a,ARRAY['जलवायु'],'published',false,true,NULL,now()-interval '14 hours',430),
('tech-ai-india-policy','भारत सरकार ने जारी की नई AI नीति, स्टार्टअप्स को मिलेगा बढ़ावा','राष्ट्रीय AI मिशन का विस्तार','नई AI नीति में स्टार्टअप्स और शोध संस्थानों को 10,000 करोड़ का बजट मिलेगा।','भारत सरकार ने आज नई कृत्रिम बुद्धिमत्ता (AI) नीति की घोषणा की। इस नीति के तहत अगले पांच वर्षों में स्टार्टअप्स और शोध संस्थानों को कुल 10,000 करोड़ रुपये का बजट आवंटित किया जाएगा।','https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1200&q=80',c_tech,a,ARRAY['AI','तकनीक'],'published',false,true,NULL,now()-interval '16 hours',980),
('entertainment-film-award','राष्ट्रीय फिल्म पुरस्कार: बिहार के निर्देशक को मिला सर्वश्रेष्ठ निर्देशक का सम्मान','गर्व का पल','बिहार के निर्देशक राजेश कुमार को सर्वश्रेष्ठ निर्देशक का पुरस्कार मिला।','इस वर्ष के राष्ट्रीय फिल्म पुरस्कार समारोह में बिहार के निर्देशक राजेश कुमार को उनकी फिल्म मिथिला की बेटी के लिए सर्वश्रेष्ठ निर्देशक का पुरस्कार दिया गया।','https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=1200&q=80',c_entertainment,a,ARRAY['सिनेमा'],'published',false,false,NULL,now()-interval '18 hours',320),
('crime-patna-police-action','पटना पुलिस की बड़ी कार्रवाई, अंतर्राज्यीय गिरोह के 8 सदस्य गिरफ़्तार','लाखों की संपत्ति बरामद','पटना पुलिस ने एक अंतर्राज्यीय चोर गिरोह के 8 सदस्यों को गिरफ़्तार किया।','पटना पुलिस ने ख़ुफ़िया सूचना के आधार पर एक अंतर्राज्यीय चोर गिरोह का पर्दाफाश किया है। 8 सदस्यों को गिरफ़्तार किया गया है।','https://images.unsplash.com/photo-1453873531674-2151bcd01707?w=1200&q=80',c_crime,a,ARRAY['पुलिस','अपराध'],'published',false,false,NULL,now()-interval '20 hours',760),
('india-economy-growth','भारत की GDP वृद्धि दर 7.4%, दुनिया में सबसे तेज़','अर्थव्यवस्था ने पकड़ी रफ़्तार','पहली तिमाही में GDP वृद्धि दर 7.4% रही जो दुनिया में सबसे तेज़ है।','चालू वित्त वर्ष की पहली तिमाही में भारत की GDP वृद्धि दर 7.4% दर्ज की गई। यह दुनिया की प्रमुख अर्थव्यवस्थाओं में सबसे तेज़ है।','https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=1200&q=80',c_india,a,ARRAY['अर्थव्यवस्था'],'published',false,true,NULL,now()-interval '22 hours',1450),
('bihar-bridge-inauguration','गंगा पर बने नए पुल का उद्घाटन, उत्तर-दक्षिण बिहार की दूरी होगी कम','विकास की नई कड़ी','मुख्यमंत्री ने गंगा पर बने नए चार लेन पुल का उद्घाटन किया।','मुख्यमंत्री ने आज गंगा नदी पर बने नए चार लेन पुल का उद्घाटन किया। यह पुल लगभग 5.5 किलोमीटर लंबा है और इसकी लागत 1,800 करोड़ रुपये है।','https://images.unsplash.com/photo-1545158535-c3f7168c28b6?w=1200&q=80',c_bihar,a,ARRAY['पुल','विकास'],'published',false,false,NULL,now()-interval '26 hours',890)
